function methodChecks(c,m){const issues=[];
const available=(value,type)=>linkedModels.some(row=>String(row.revisionId)===String(value)&&row.modelType===type);
if(!available(c?.router?.model,'chat'))issues.push('请选择可用的簇路由模型连接');
if(c?.recall?.mode!=='vector'&&!available(c?.recall?.model,'chat'))issues.push('请选择可用的 LLM 召回模型连接');
if(c?.recall?.mode!=='llm'&&!available(c?.recall?.embeddingModel,'embedding'))issues.push('请选择可用的向量编码模型连接');
if(!available(c?.judge?.model,'chat'))issues.push('请选择可用的独立精判模型连接');
if(+c.router?.minClusters>+c.router?.maxClusters)issues.push('选簇数量上下限冲突');if(+c.recall?.minCandidates>+c.recall?.maxCandidates)issues.push('召回数量上下限冲突');if(c.recall?.mode!=='llm'&&!c.recall?.index)issues.push('向量召回缺少索引');if(!c.judge?.prompt?.includes('{{abstract}}')||!c.judge?.prompt?.includes('{{candidates}}'))issues.push('精判提示词缺少 {{abstract}} 或 {{candidates}}');if(!linkedKnowledge.find(k=>k.id===m.kbId)?.versions.some(v=>v.number===methodSource()?.knowledgeVersion))issues.push('引用的知识库版本不存在');return issues}
function stageFields(id,c,disabled){const b=(p)=>`method:${id}:${p}`, x={disabled};const llm=modelOptions('chat',c.model);const txt=(l,p,extra={})=>field(l,c[p],b(p),{...extra,disabled});let basic='',adv='';switch(id){case 'parse':basic=txt('参与识别的输入字段','fields',{hint:'多个字段使用顿号分隔'})+txt('文本组织方式','layout',{type:'select',options:['结构化拼接','原文顺序拼接','仅摘要']})+txt('摘要最大截取长度','maxLen',{type:'number',min:100});adv=txt('缺失字段处理','missing',{type:'select',options:['跳过缺失字段','阻止执行','使用空值']})+txt('文本清洗规则','clean',{type:'textarea',rows:3});break;
case 'router':basic=txt('模型连接','model',{type:'select',options:llm})+txt('选簇数量上限','maxClusters',{type:'number',min:1});adv=txt('最少选簇数量','minClusters',{type:'number',min:1})+txt('补充策略','supplement',{type:'select',options:['不足时补充邻近簇','不补充']})+txt('路由提示词','prompt',{type:'textarea',rows:6});break;
case 'recall':basic=txt('学科召回策略','mode',{type:'select',options:[['llm','LLM 分层召回'],['vector','向量召回'],['hybrid','混合召回']]})
 +(c.mode!=='vector'?txt('LLM 召回模型','model',{type:'select',options:llm}):'')
 +(c.mode!=='llm'?txt('向量编码模型','embeddingModel',{type:'select',options:modelOptions('embedding',c.embeddingModel)}):'')
 +txt('候选学科数量上限','maxCandidates',{type:'number',min:1});adv=txt('最低候选数量','minCandidates',{type:'number',min:1})+txt('候选补足规则','fill',{type:'select',options:['按照簇内覆盖补足','不补足','按相似度补足']})+(c.mode!=='llm'?txt('向量索引','index')+txt('向量召回权重（0–1）','vectorWeight',{type:'number',min:0,max:1}):'')+(c.mode!=='vector'?txt('候选召回提示词','prompt',{type:'textarea'}):'');break;
case 'judge':basic=txt('模型连接','model',{type:'select',options:llm})+txt('规则模板','template',{type:'select',options:['学科任务与边界精判','学科核心任务精判','简化相关性精判']});adv=txt('完整提示词','prompt',{type:'textarea',rows:7,hint:'必须保留 {{abstract}} 与 {{candidates}} 两个变量'})+txt('Temperature','temperature',{type:'number',min:0,max:2})+txt('最大输出 Token','maxTokens',{type:'number',min:256});break;
case 'post':basic=txt('高度相关学科数量上限','maxStrong',{type:'number',min:1})+txt('最低保留等级','minLevel',{type:'select',options:[['0','0 — 低相关'],['1','1 — 中相关'],['2','2 — 高相关']]})+txt('最多输出学科数','outputLimit',{type:'number',min:1});adv=txt('排序规则','order',{type:'select',options:['相关等级优先','召回分数优先','综合排序']})+txt('失败处理策略','failure',{type:'select',options:['保留原始结果','标记为待检查','终止当前样本']});break;
case 'element':basic=txt('模型连接','model',{type:'select',options:llm})+txt('要素类型定义','elements',{type:'textarea',rows:3});adv=txt('分句规则','sentences',{type:'select',options:['按标点分句','按段落分句','不分句']})+txt('抽取提示词','prompt',{type:'textarea',rows:5})+txt('空要素处理','empty',{type:'select',options:['保留空要素','跳过空要素','提示人工检查']});break;
case 'mapping':basic=txt('学科识别策略','mode',{type:'select',options:[['hybrid','混合检索 + 模型精判'],['llm','LLM 直接识别'],['vector','向量检索']]})+(c.mode!=='vector'?txt('精判模型连接','model',{type:'select',options:llm}):'')+(c.mode!=='llm'?txt('向量索引','index'):'')+txt('要素候选数量上限','maxCandidates',{type:'number',min:1});adv=(c.mode==='hybrid'?txt('向量召回权重','vectorWeight',{type:'number',min:0,max:1}):'')+txt('上下文范围','context',{type:'select',options:['当前句','当前句及相邻两句','全文上下文']})+(c.mode!=='vector'?txt('精判提示词','prompt',{type:'textarea',rows:5}):'');break;
case 'score':basic=txt('关联等级阈值','threshold',{type:'select',options:[['0','0 — 所有相关学科'],['1','1 — 中相关及以上'],['2','2 — 高相关']]})+txt('K 的分母方式','denominator',{type:'select',options:['有效要素数量','全部要素数量','四类固定要素']});adv=txt('主学科策略','mainPolicy',{type:'select',options:['以主学科精判结果为准','以相关度最高者为准']})+txt('相似度缺失处理','missing',{type:'select',options:['标记并排除缺失值','用默认距离填充','终止计算']});break;}
return `<div class="inspector-body"><div class="label" style="margin-bottom:12px">基础配置</div>${basic}<button class="advanced-toggle" data-action="methodAdvanced">高级配置 ${ic(ui.methodAdvanced?'up':'down',15)}</button>${ui.methodAdvanced?`<div class="label" style="margin-bottom:13px">高级配置</div>${adv}`:''}${disabled?`<div class="config-readonly">${ic('lock',14)}　当前为已保存版本，仅支持查看。点击「基于此创建草稿」后修改。</div>`:`<div class="hint mt18">修改仅作用于当前草稿，不影响已保存版本或历史运行记录。</div>`}</div>`}
function flowNode(id,label,meta){const active=ui.methodStage===id,source=methodSource(),m=M(),dirty=ui.methodView==='draft'&&!!m.draft&&ui.methodDirty;return `<button class="flow-node ${active?'active':''} ${dirty&&active?'dirty':''}" data-action="stage:${id}"><span class="node-name">${esc(label)}</span><span class="node-meta">${meta}</span></button>`}
const arrow=()=>`<span class="flow-arrow">${ic('arrow',14)}</span>`;
function renderMethodDetail(){const m=M(),source=methodSource(),isDraft=ui.methodView==='draft'&&!!m.draft,readonly=!isDraft,c=source.config,checks=methodChecks(c,m);const actions=isDraft?`${btn('保存草稿','methodSaveDraft')}${btn('保存新版本','methodSaveVersion','primary')}`:`${btn('基于此创建草稿','methodCreateDraft','secondary')}${btn('前往单篇调试','methodDebug:'+m.id,'primary')}`;return `<div class="mini-nav"><a data-action="nav:methods">识别方法</a>${ic('chevron',13)}<span>${esc(m.name)}</span></div>${pageHead('METHOD / CONFIGURATION',esc(m.name),esc(m.desc),actions)}<div class="meta-strip"><span>所有者 <strong>${esc(m.owner)}</strong></span><span>学科体系 <strong>${esc(m.tag)}</strong></span><span>依赖知识库 <a class="text-green bold" data-action="kbOpen:${m.kbId}" style="cursor:pointer">${esc(kbName(m.kbId))}</a> <strong>${esc(source.knowledgeVersion||m.kbVersion)}</strong></span><span>状态 ${badge(isDraft?'草稿 · 可编辑':'已保存 '+source.number,isDraft?'amber':'green')}</span></div><div class="tabbar"><button class="tab ${ui.methodTab==='flow'?'active':''}" data-action="methodTab:flow">流程配置</button><button class="tab ${ui.methodTab==='versions'?'active':''}" data-action="methodTab:versions">版本记录 <span class="muted">${m.versions.length}</span></button></div>${ui.methodTab==='versions'?renderMethodVersions(m):`<div class="toolbar"><div class="toolbar-left"><span class="bold smalltext">配置对象</span><select class="filter-select" data-filter="methodView">${m.draft?`<option value="draft" ${isDraft?'selected':''}>草稿 · ${esc(m.draft.baseVersion||'新方法')}</option>`:''}${m.versions.map(v=>`<option value="${esc(v.number)}" ${!isDraft&&ui.methodVersion===v.number?'selected':''}>已保存 ${esc(v.number)}</option>`).join('')}</select>${isDraft?fieldInlineKnowledge(m,source.knowledgeVersion):''}</div><div class="toolbar-right">${btn(ic('checkcircle',15)+' 配置校验','methodValidate','small')}${btn('前往调试 '+ic('arrow',13),'methodDebug:'+m.id,'small ghost')}</div></div><div class="flow-layout"><div class="flow-left"><section class="panel flow-board"><div class="flow-caption"><strong style="color:#53695b">识别流程</strong><span>点击节点配置阶段参数 ${badge('双分支 · 汇合')}</span></div><div class="flow-start">${flowNode('parse','内容输入与解析','输入阶段')}</div><div style="display:flex;align-items:center;justify-content:center;color:#96aa9a;height:17px">${ic('down',16)}</div><div class="flow-lane"><div class="lane-head"><span class="badge green">分支 A</span> 学科路由与判定</div><div class="lane-nodes">${flowNode('router','簇路由','模型 / 规则')}${arrow()}${flowNode('recall','学科召回','策略 / 候选')}${arrow()}${flowNode('judge','独立精判','模型 / 提示词')}${arrow()}${flowNode('post','后处理','等级 / 排序')}</div></div><div class="flow-lane"><div class="lane-head"><span class="badge green">分支 B</span> 科研要素与学科映射</div><div class="lane-nodes">${flowNode('element','研究要素抽取','模型 / 要素')}${arrow()}${flowNode('mapping','要素学科识别','索引 / 精判')}<div style="flex:1.2;color:#93a596;font-size:11px;text-align:center">合并至交叉度计算 ${ic('arrow',13)}</div></div></div><div class="flow-merge"><span class="merge-marker">两个分支汇合</span>${ic('down',14)}${flowNode('score','交叉度计算','ICI / N · D · K')}${arrow()}<span class="badge green">结果</span></div></section><section class="panel panel-pad mt18"><div class="section-head"><strong>配置完整性</strong>${badge(checks.length?checks.length+' 项待检查':'通过基础校验',checks.length?'amber':'green')}</div>${checks.length?`<div class="validation-list">${checks.map(a=>`<div class="validation-item text-danger">${ic('alert',15)}${esc(a)}</div>`).join('')}</div>`:`<div class="inline-note condensed">${ic('checkcircle',16)}<span>当前版本的主要配置项已通过基础检查。正式运行仍需验证服务和资源可用性。</span></div>`}</section></div><section class="panel inspector"><div class="inspector-head"><div class="inspector-title">${esc(stageName(ui.methodStage))} ${readonly?badge('只读'):badge('草稿编辑','amber')}</div><div class="inspector-sub">选中节点的规则与参数。基础配置优先展示，高级选项按需展开。</div></div>${stageFields(ui.methodStage,c[ui.methodStage],readonly)}</section></div>`}`}
function fieldInlineKnowledge(m,v){return `<label style="display:flex;align-items:center;gap:7px;font-size:12px;color:#7b8a7e">知识库版本 <select class="filter-select" data-filter="methodKnowledgeVersion">${(linkedKnowledge.find(k=>k.id===m.kbId)?.versions||[]).map(x=>`<option value="${esc(x.number)}" ${x.number===v?'selected':''}>${esc(x.number)}</option>`).join('')}</select></label>`}
function renderMethodVersions(m){return `<section class="panel"><div class="version-row heading"><div>版本</div><div>保存说明</div><div>时间 / 保存人</div><div>知识库版本</div><div>操作</div></div>${m.versions.map(v=>`<div class="version-row"><div>${badge(v.number,v.number===m.defaultVersion?'green':'neutral')}${v.number===m.defaultVersion?`<div class="tiny muted mt8">默认使用</div>`:''}</div><div><strong>${esc(v.summary)}</strong><div class="tiny muted mt8">已保存快照 · 配置不可直接修改</div></div><div>${esc(v.date)}<div class="muted tiny mt8">${esc(v.author)}</div></div><div>${esc(kbName(m.kbId))}<div class="tiny muted mt8">${esc(v.knowledgeVersion)}</div></div><div class="card-actions" style="justify-content:flex-start">${btn('查看','methodVersion:'+v.number,'small')}${btn('基于此创建草稿','methodDraftFrom:'+v.number,'small')}${btn('单篇调试','methodDebugVersion:'+v.number,'small')}${v.number!==m.defaultVersion?btn('设为默认','methodDefault:'+v.number,'small ghost'):''}</div></div>`).join('')}</section>`}
const DEBUG_SAMPLE={type:'学术论文',title:'大语言模型驱动的科研文本学科交叉识别与知识整合测度',keywords:'大语言模型；学科交叉；科研文本；知识整合',abstract:'针对传统基于引文和学科标签的交叉识别方法难以解释知识整合过程的问题，本研究提出基于大语言模型的多阶段文本分析框架。首先抽取研究问题、理论、方法与发现等科研要素；随后结合学科画像和学科边界进行候选学科召回、独立精判和要素级学科映射；最后融合关联强度、学科差异与要素覆盖信息，形成具有可解释性的交叉度指标。',journal:'信息资源管理学报',doi:'',year:'2026',externalId:'P-2026-001'};
